struct VSWorldScene{struct ObjectHandle{int local=1,generation=1;VSWorldContracts::OwnerKind kind=VSWorldContracts::OwnerKind::Object;};struct LocalTransform{LLVector3 position,scale;LLQuaternion rotation;};struct Focus{LLQuaternion renderRotation;bool current()const{return true;}};std::vector<ObjectHandle>children;std::map<int,LocalTransform>poses;std::map<int,int>generations;bool ready=true,refuse=false;int writes=0;std::shared_ptr<int>reservations=std::make_shared<int>(0);bool current(ObjectHandle h)const{return ready&&generations.count(h.local)&&generations.at(h.local)==h.generation;}std::optional<std::vector<ObjectHandle>>directChildren(ObjectHandle h){return current(h)?std::optional{children}:std::nullopt;}std::optional<LocalTransform>objectEditTransform(ObjectHandle h){return current(h)?std::optional{poses.at(h.local)}:std::nullopt;}std::optional<LocalTransform>objectLocalTransform(ObjectHandle h){return objectEditTransform(h);}std::optional<Focus>focusObject(ObjectHandle h,int){return current(h)?std::optional{Focus{{4}}}:std::nullopt;}std::shared_ptr<const VSResourceBudget::Reservation>reserveSpatialBytes(std::size_t){return refuse?nullptr:std::make_shared<VSResourceBudget::Reservation>(reservations);}bool previewLocalTransform(ObjectHandle h,const LocalTransform&p,U32 bits){if(!current(h))return false;++writes;if(bits&1)poses[h.local].position=p.position;if(bits&2)poses[h.local].rotation=p.rotation;return true;}};
