int main(){using H=VSWorldScene::ObjectHandle;for(unsigned i=0;i<20000;++i){world.children={H{2}};world.generations={{1,1},{2,1}};VSObjectSelection selector;world.poses[1]={{float(i%17),float(i%11),float(i%7)},{1,1,1},{float(i%3)*.1f,float(i%5)*.1f,float(i%7)*.1f,.75f}};world.poses[2]={{3,4,5},{1,1,1},{0,0,0,1}};std::vector<LLVector3>positions;std::vector<LLQuaternion>rotations;assert(selector.saveUnselectedChildrenPosition({},positions));assert(selector.saveUnselectedChildrenRotation({},rotations));world.poses[1].position={float(i%13),float(i%19),float(i%23)};world.poses[1].rotation={.25f,float(i%3)*.1f,.5f,.75f};ReferenceChild expected;original(&expected,rotations,positions,~world.poses[1].rotation,world.poses[1].position);assert(selector.resetChildrenRotationAndPosition({},rotations,positions));assert(world.poses[2].position==expected.position&&world.poses[2].rotation==expected.rotation);}}
